from collections import Counter
def solve(I):
    H,W=len(I),len(I[0])
    bg=Counter(v for r in I for v in r).most_common(1)[0][0]
    O=[row[:] for row in I]
    # find maximal uniform rectangles: each non-bg cell belongs to some rect; split by color change rows/cols?
    # Use connected components of same color (4-conn); each component is a rectangle here.
    seen=[[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg and not seen[r][c]:
                v=I[r][c]; comp=[]; st=[(r,c)]; seen[r][c]=True
                while st:
                    rr,cc=st.pop(); comp.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and I[nr][nc]==v:
                            seen[nr][nc]=True; st.append((nr,nc))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,r2=min(rs),max(rs); c0,c2=min(cs),max(cs)
                if len(comp)==(r2-r0+1)*(c2-c0+1) and all(I[p[0]][p[1]]==v for p in comp):
                    for rr in range(r0+1,r2):
                        for cc in range(c0+1,c2):
